-- Table: BudgetMonthRow
DROP TABLE IF EXISTS BudgetMonthRow;

CREATE TABLE IF NOT EXISTS BudgetMonthRow (
    BudgetMonthRowId TEXT    NOT NULL
                             PRIMARY KEY,
    BudgetMonthId    TEXT    NOT NULL,
    TemplateRowId    TEXT    NULL,
    Name             TEXT    NOT NULL,
    SortIndex        INTEGER NOT NULL
                             DEFAULT 0,
    PlannedAmount    REAL    NOT NULL,
    FOREIGN KEY (
        BudgetMonthId
    )
    REFERENCES BudgetMonth (BudgetMonthId),
    FOREIGN KEY (
        TemplateRowId
    )
    REFERENCES BudgetTemplateRow (TemplateRowId) 
);


-- Table: BudgetTemplateRow
DROP TABLE IF EXISTS BudgetTemplateRow;

CREATE TABLE IF NOT EXISTS BudgetTemplateRow (
    TemplateRowId TEXT    NOT NULL
                          PRIMARY KEY,
    Name          TEXT    NOT NULL,
    SortIndex     INTEGER NOT NULL
                          DEFAULT 0,
    DefaultAmount REAL    NOT NULL,
    IsActive      INTEGER NOT NULL
                          DEFAULT 1
);


-- Table: Payee
DROP TABLE IF EXISTS Payee;

CREATE TABLE IF NOT EXISTS Payee (
    PayeeId                 TEXT    PRIMARY KEY,
    PayeeName               TEXT    NOT NULL,
    IncludeInBudgetTemplate INTEGER NOT NULL
                                    DEFAULT 0,
    SortIndex               INTEGER NOT NULL
                                    DEFAULT 0,
    IsActive                INTEGER NOT NULL
                                    DEFAULT 1,
    WebsiteId               TEXT    NULL,
    DefaultAccountId        TEXT    NULL,
    DefaultAmount           NUMERIC NULL,
    UNIQUE (
        PayeeName
    )
);

