INSERT INTO SqlQuery (
                         QueryName,
                         Description,
                         SqlText,
                         CreatedUtc,
                         Category,
                         IsActive
                     )
                     VALUES (
                         'BudgetMonth.CopyTemplatePayees',
                         'Copies payees that are flagged for inclusion in the budget template into BudgetMonthPayee for a specific budget month. Used when creating a new budget so the new month starts with the standard set of budget items.',
                         'INSERT INTO [BudgetMonthPayee]
(
    [BudgetMonthPayeeId],
    [BudgetMonthId],
    [PayeeId],
    [SortIndex],
    [PlannedAmount],
    [AccountId]
)
SELECT
    @BudgetMonthId || ''-'' || p.[PayeeId],
    @BudgetMonthId,
    p.[PayeeId],
    p.[SortIndex],
    COALESCE(p.[DefaultAmount],0),
    p.[DefaultAccountId]
FROM [Payee] p
WHERE p.[IncludeInBudgetTemplate] = 1;',
                         '2026-03-11 20:05:02',
                         'Budget',
                         1
                     );

