INSERT INTO SqlQuery (
                         QueryName,
                         Description,
                         SqlText,
                         CreatedUtc,
                         Category,
                         IsActive
                     )
                     VALUES (
                         'BudgetMonthPayee.ImportFromStage',
                         'Imports BudgetMonthPayee rows from legacy stage_Budget_old data by mapping legacy Payee and Account ids into the current schema and upserting by BudgetMonthPayeeId.',
                         'INSERT INTO [BudgetMonthPayee]
(
    [BudgetMonthPayeeId],
    [BudgetMonthId],
    [PayeeId],
    [SortIndex],
    [PlannedAmount],
    [AccountId]
)
SELECT
    printf(
        ''%04d-%02d-%s'',
        sb.[BudgetYear],
        sb.[BudgetMonth],
        p.[PayeeId]
    ),

    printf(''%04d-%02d'', sb.[BudgetYear], sb.[BudgetMonth]),

    p.[PayeeId],

    COALESCE(p.[SortIndex],0),

    sb.[TotalAmount],

    CASE
        WHEN sb.[BankAccountID] IS NULL
          OR sb.[BankAccountID] = 0
        THEN NULL
        ELSE a.[AccountId]
    END

FROM [stage_Budget_old] sb
INNER JOIN [Payee] p
    ON p.[PayeeId] =
       ''legacy-payee-'' || CAST(sb.[PayeeID] AS TEXT)
LEFT JOIN [Account] a
    ON a.[AccountId] =
       ''legacy-bankaccount-'' || CAST(sb.[BankAccountID] AS TEXT)

ON CONFLICT([BudgetMonthPayeeId]) DO UPDATE SET
    [SortIndex]     = excluded.[SortIndex],
    [PlannedAmount] = excluded.[PlannedAmount],
    [AccountId]     = excluded.[AccountId];',
                         '2026-03-11 20:05:02',
                         'Import',
                         1
                     );

INSERT INTO SqlQuery (
                         QueryName,
                         Description,
                         SqlText,
                         CreatedUtc,
                         Category,
                         IsActive
                     )
                     VALUES (
                         'BudgetMonthPayee.PreviewImportFromStage',
                         'Preview query for budget migration. Shows the BudgetMonthPayee rows that would be created from stage_Budget_old before running the import.',
                         'SELECT
    printf(
        ''%04d-%02d-%s'',
        sb.[BudgetYear],
        sb.[BudgetMonth],
        p.[PayeeId]
    ) AS [BudgetMonthPayeeId],

    printf(''%04d-%02d'', sb.[BudgetYear], sb.[BudgetMonth]) AS [BudgetMonthId],

    p.[PayeeId],
    p.[PayeeName],
    COALESCE(p.[SortIndex], 0) AS [SortIndex],
    sb.[TotalAmount] AS [PlannedAmount],

    CASE
        WHEN sb.[BankAccountID] IS NULL
          OR sb.[BankAccountID] = 0
        THEN NULL
        ELSE a.[AccountId]
    END AS [AccountId],

    sb.[BudgetYear],
    sb.[BudgetMonth],
    sb.[PayeeID] AS [StagePayeeID],
    sb.[BankAccountID] AS [StageBankAccountID]

FROM [stage_Budget_old] sb
INNER JOIN [Payee] p
    ON p.[PayeeId] = ''legacy-payee-'' || CAST(sb.[PayeeID] AS TEXT)
LEFT JOIN [Account] a
    ON a.[AccountId] = ''legacy-bankaccount-'' || CAST(sb.[BankAccountID] AS TEXT)

ORDER BY
    sb.[BudgetYear],
    sb.[BudgetMonth],
    p.[SortIndex],
    p.[PayeeName];',
                         '2026-03-12 02:13:24',
                         'Import',
                         1
                     );

