INSERT INTO SqlQuery (
                         QueryName,
                         Description,
                         SqlText,
                         CreatedUtc,
                         Category,
                         IsActive
                     )
                     VALUES (
                         'BudgetMonthPayee.SelectByBudgetMonthId',
                         'Returns the full catalog of budget items for a specific BudgetMonthId including PayeeName for display in the monthly budget grid.',
                         'SELECT
    bmp.BudgetMonthPayeeId,
    bmp.BudgetMonthId,
    bmp.PayeeId,
    p.PayeeName,
    p.SortIndex,
    bmp.PlannedAmount,
    bmp.AccountId,
    b.BankName,
    a.AccountNickname,
    CASE
        WHEN a.AccountId IS NULL THEN NULL
        WHEN b.BankName IS NULL OR TRIM(b.BankName) = '''' THEN a.AccountNickname
        WHEN a.AccountNickname IS NULL OR TRIM(a.AccountNickname) = '''' THEN b.BankName
        ELSE b.BankName || '' - '' || a.AccountNickname
    END AS AccountDisplayName
FROM [BudgetMonthPayee] bmp
INNER JOIN [Payee] p
    ON p.PayeeId = bmp.PayeeId
LEFT JOIN [Account] a
    ON a.AccountId = bmp.AccountId
LEFT JOIN [Bank] b
    ON b.BankId = a.BankId
WHERE bmp.BudgetMonthId = @BudgetMonthId
ORDER BY p.SortIndex, p.PayeeName;',
                         '2026-03-12 02:19:55',
                         'Budget',
                         1
                     );

