INSERT INTO SqlQuery (
                         QueryName,
                         Description,
                         SqlText,
                         CreatedUtc,
                         Category,
                         IsActive
                     )
                     VALUES (
                         'BudgetMonth.MissingMonthsForYear',
                         'Returns months within a specific year that do not yet have a BudgetMonth
record. Used by the budget year view to show which months are still
available for budget creation.',
                         'SELECT
    m.MonthNumber,
    CASE m.MonthNumber
        WHEN 1 THEN ''January''
        WHEN 2 THEN ''February''
        WHEN 3 THEN ''March''
        WHEN 4 THEN ''April''
        WHEN 5 THEN ''May''
        WHEN 6 THEN ''June''
        WHEN 7 THEN ''July''
        WHEN 8 THEN ''August''
        WHEN 9 THEN ''September''
        WHEN 10 THEN ''October''
        WHEN 11 THEN ''November''
        WHEN 12 THEN ''December''
    END AS MonthName,
    printf(''%04d-%02d'', @Year, m.MonthNumber) AS BudgetMonthId
FROM
(
    SELECT 1 AS MonthNumber UNION ALL
    SELECT 2 UNION ALL
    SELECT 3 UNION ALL
    SELECT 4 UNION ALL
    SELECT 5 UNION ALL
    SELECT 6 UNION ALL
    SELECT 7 UNION ALL
    SELECT 8 UNION ALL
    SELECT 9 UNION ALL
    SELECT 10 UNION ALL
    SELECT 11 UNION ALL
    SELECT 12
) m
LEFT JOIN BudgetMonth bm
    ON bm.Year = @Year
   AND bm.Month = m.MonthNumber
WHERE bm.BudgetMonthId IS NULL
ORDER BY m.MonthNumber;',
                         '2026-03-13 01:23:19',
                         'Budget',
                         1
                     );

