INSERT INTO SqlQuery (
                         QueryName,
                         Description,
                         SqlText,
                         CreatedUtc,
                         Category,
                         IsActive
                     )
                     VALUES (
                         'Tag.GetByEntity',
                         'Returns tags assigned to a single entity using the generic TagAssignment model.',
                         'SELECT
    ta.[TagAssignmentId],
    ta.[TagId],
    t.[TagName],
    t.[SortIndex] AS [TagSortIndex],
    ta.[EntityType],
    ta.[EntityId],
    ta.[SortIndex] AS [AssignmentSortIndex],
    ta.[IsActive]
FROM [TagAssignment] ta
JOIN [Tag] t
    ON t.[TagId] = ta.[TagId]
WHERE ta.[EntityType] = @EntityType
  AND ta.[EntityId] = @EntityId
  AND ta.[IsActive] = 1
  AND t.[IsActive] = 1
ORDER BY t.[SortIndex], t.[TagName], ta.[SortIndex], ta.[TagAssignmentId];',
                         '2026-03-29 19:16:26',
                         'Tagging',
                         1
                     );

