INSERT INTO SqlQuery (
                         QueryName,
                         Description,
                         SqlText,
                         CreatedUtc,
                         Category,
                         IsActive
                     )
                     VALUES (
                         'Website.GetAllWithTagSummary',
                         'Returns all active websites with aggregated tag list',
                         '
    SELECT
        w.WebsiteId,
        w.Name,
        w.Url,
        COALESCE(
            REPLACE(GROUP_CONCAT(DISTINCT t.TagName), '','', '', ''),
            ''''
        ) AS Tags
    FROM [Website] w
    LEFT JOIN [TagAssignment] ta
        ON ta.[EntityType] = ''Website''
        AND ta.[EntityId] = w.[WebsiteId]
        AND ta.[IsActive] = 1
    LEFT JOIN [Tag] t
        ON t.[TagId] = ta.[TagId]
        AND t.[IsActive] = 1
    WHERE w.[IsActive] = 1
    GROUP BY
        w.[WebsiteId],
        w.[Name],
        w.[Url]
    ORDER BY
        w.[Name]
    ',
                         '2026-03-30 02:01:43',
                         'Website',
                         1
                     );

INSERT INTO SqlQuery (
                         QueryName,
                         Description,
                         SqlText,
                         CreatedUtc,
                         Category,
                         IsActive
                     )
                     VALUES (
                         'Tag.DeactivateTree',
                         'Soft-deactivates a tag and all descendant tags by TagId',
                         '
    WITH RECURSIVE [TagTree] AS (
        SELECT [TagId]
        FROM [Tag]
        WHERE [TagId] = @TagId

        UNION ALL

        SELECT t.[TagId]
        FROM [Tag] t
        INNER JOIN [TagTree] tt
            ON t.[ParentTagId] = tt.[TagId]
    )
    UPDATE [Tag]
    SET [IsActive] = 0
    WHERE [TagId] IN (
        SELECT [TagId]
        FROM [TagTree]
    );
    ',
                         '2026-03-31 00:13:55',
                         'Tag',
                         1
                     );

INSERT INTO SqlQuery (
                         QueryName,
                         Description,
                         SqlText,
                         CreatedUtc,
                         Category,
                         IsActive
                     )
                     VALUES (
                         'TagAssignment.DeactivateByTagTree',
                         'Soft-deactivates tag assignments for a tag and all descendant tags by TagId',
                         '
    WITH RECURSIVE [TagTree] AS (
        SELECT [TagId]
        FROM [Tag]
        WHERE [TagId] = @TagId

        UNION ALL

        SELECT t.[TagId]
        FROM [Tag] t
        INNER JOIN [TagTree] tt
            ON t.[ParentTagId] = tt.[TagId]
    )
    UPDATE [TagAssignment]
    SET [IsActive] = 0
    WHERE [TagId] IN (
        SELECT [TagId]
        FROM [TagTree]
    );
    ',
                         '2026-03-31 00:14:25',
                         'TagAssignment',
                         1
                     );

