-- Table: stage_Budget_old
DROP TABLE IF EXISTS stage_Budget_old;

CREATE TABLE IF NOT EXISTS stage_Budget_old (
    BudgetYear    "[INTEGER]" DEFAULT (2012) 
                              NOT NULL
                              COLLATE NOCASE,
    BudgetMonth   "[INTEGER]" DEFAULT (0) 
                              NOT NULL
                              COLLATE NOCASE,
    PayeeID       "[INTEGER]" DEFAULT (0) 
                              NOT NULL
                              COLLATE NOCASE,
    PayeeName     "[TEXT]"    DEFAULT ('') 
                              NOT NULL
                              COLLATE NOCASE,
    Status        "[TEXT]"    DEFAULT ('') 
                              NOT NULL
                              COLLATE NOCASE,
    TotalAmount   "[REAL]"    DEFAULT (0) 
                              NOT NULL
                              COLLATE NOCASE,
    LaurenPercent "[REAL]"    DEFAULT (0.5) 
                              NOT NULL
                              COLLATE NOCASE,
    NickPercent   "[REAL]"    DEFAULT (0.5) 
                              NOT NULL
                              COLLATE NOCASE,
    Notes         "[TEXT]"    DEFAULT ('') 
                              NOT NULL
                              COLLATE NOCASE,
    DateSent      "[DATE]"    DEFAULT ('2/22/2012 12:00:00 AM') 
                              NOT NULL
                              COLLATE NOCASE,
    BankAccountID "[INTEGER]" DEFAULT (0) 
                              NOT NULL
                              COLLATE NOCASE,
    TransActionID "[INTEGER]" DEFAULT (0) 
                              NOT NULL
                              COLLATE NOCASE,
    [Group]       "[INTEGER]" DEFAULT (0) 
                              NOT NULL
                              COLLATE NOCASE,
    Confirm       "[TEXT]"    DEFAULT ('') 
                              NOT NULL
                              COLLATE NOCASE,
    PieChart      "[INTEGER]" DEFAULT (1) 
                              NOT NULL
                              COLLATE NOCASE,
    PRIMARY KEY (
        BudgetYear,
        BudgetMonth,
        PayeeID
    )
);

