-- Table: stage_BudgetTemplate
DROP TABLE IF EXISTS stage_BudgetTemplate;

CREATE TABLE IF NOT EXISTS stage_BudgetTemplate (
    PayeeID       "[INTEGER]" DEFAULT (0) 
                              NOT NULL
                              COLLATE NOCASE,
    PayeeName     "[TEXT]"    DEFAULT ('') 
                              NOT NULL
                              COLLATE NOCASE,
    BankAccountID "[INTEGER]" DEFAULT (0) 
                              NOT NULL
                              COLLATE NOCASE,
    TotalAmount   "[REAL]"    DEFAULT (0) 
                              NOT NULL
                              COLLATE NOCASE,
    LaurenPercent "[REAL]"    DEFAULT (0) 
                              NOT NULL
                              COLLATE NOCASE,
    NickPercent   "[REAL]"    DEFAULT (0) 
                              NOT NULL
                              COLLATE NOCASE,
    Active        "[INTEGER]" DEFAULT (1) 
                              NOT NULL
                              COLLATE NOCASE,
    PRIMARY KEY (
        PayeeID
    )
);

