-- Table: stage_Payee
DROP TABLE IF EXISTS stage_Payee;

CREATE TABLE IF NOT EXISTS stage_Payee (
    PayeeID              "[INTEGER]" DEFAULT (0) 
                                     NOT NULL
                                     COLLATE NOCASE,
    Balance              "[REAL]"    DEFAULT (0) 
                                     NOT NULL
                                     COLLATE NOCASE,
    StandardPayment      "[REAL]"    DEFAULT (0) 
                                     NOT NULL
                                     COLLATE NOCASE,
    StandardPayDate      "[INTEGER]" DEFAULT (0) 
                                     NOT NULL
                                     COLLATE NOCASE,
    BudgetID             "[INTEGER]" DEFAULT (0) 
                                     NOT NULL
                                     COLLATE NOCASE,
    WebID                "[INTEGER]" DEFAULT (0) 
                                     NOT NULL
                                     COLLATE NOCASE,
    StandardPayAccountID "[INTEGER]" DEFAULT (0) 
                                     NOT NULL
                                     COLLATE NOCASE,
    PaymentMethod        "[TEXT]"    DEFAULT ('BillPay') 
                                     NOT NULL
                                     COLLATE NOCASE,
    Category             "[TEXT]"    DEFAULT ('') 
                                     NOT NULL
                                     COLLATE NOCASE,
    Name                 "[TEXT]"    DEFAULT ('') 
                                     NOT NULL
                                     COLLATE NOCASE,
    Description          "[TEXT]"    DEFAULT ('') 
                                     NOT NULL
                                     COLLATE NOCASE,
    AccountNumber        "[TEXT]"    DEFAULT ('') 
                                     NOT NULL
                                     COLLATE NOCASE,
    PhoneNumber          "[TEXT]"    DEFAULT ('') 
                                     NOT NULL
                                     COLLATE NOCASE,
    Address1             "[TEXT]"    DEFAULT ('') 
                                     NOT NULL
                                     COLLATE NOCASE,
    Address2             "[TEXT]"    DEFAULT ('') 
                                     NOT NULL
                                     COLLATE NOCASE,
    Address3             "[TEXT]"    DEFAULT ('') 
                                     NOT NULL
                                     COLLATE NOCASE,
    City                 "[TEXT]"    DEFAULT ('') 
                                     NOT NULL
                                     COLLATE NOCASE,
    State                "[TEXT]"    DEFAULT ('') 
                                     NOT NULL
                                     COLLATE NOCASE,
    Zipcode              "[TEXT]"    DEFAULT ('') 
                                     NOT NULL
                                     COLLATE NOCASE,
    Include              "[INTEGER]" DEFAULT (0) 
                                     NOT NULL
                                     COLLATE NOCASE,
    FixedAmount          "[INTEGER]" DEFAULT (0) 
                                     NOT NULL
                                     COLLATE NOCASE,
    PRIMARY KEY (
        PayeeID
    )
);

