-- Table: stage_Web
DROP TABLE IF EXISTS stage_Web;

CREATE TABLE IF NOT EXISTS stage_Web (
    WebID          "[INTEGER]" DEFAULT (0) 
                               NOT NULL
                               COLLATE NOCASE,
    URL            "[TEXT]"    DEFAULT ('') 
                               NOT NULL
                               COLLATE NOCASE,
    UserId         "[TEXT]"    DEFAULT ('') 
                               NOT NULL
                               COLLATE NOCASE,
    PW             "[TEXT]"    DEFAULT ('') 
                               NOT NULL
                               COLLATE NOCASE,
    Name           "[TEXT]"    DEFAULT ('') 
                               NOT NULL
                               COLLATE NOCASE,
    PwLength       "[INTEGER]" DEFAULT (10) 
                               NOT NULL
                               COLLATE NOCASE,
    LowerCaseChar  "[TEXT]"    DEFAULT ('abcdefghijklmnopqrstuvwxyz') 
                               NOT NULL
                               COLLATE NOCASE,
    UpperCaseChars "[TEXT]"    DEFAULT ('ABCDEFGHIJKLMNOPQRSTUVWXYZ') 
                               NOT NULL
                               COLLATE NOCASE,
    NumericChars   "[TEXT]"    DEFAULT ('1234567890') 
                               NOT NULL
                               COLLATE NOCASE,
    SpecialChars   "[TEXT]"    DEFAULT ('!#$%&()*+-_,./\;:<>[]|~`{}£') 
                               NOT NULL
                               COLLATE NOCASE,
    PRIMARY KEY (
        WebID
    )
);

