    WebID          "[INTEGER]" DEFAULT (0) 
                               NOT NULL
                               COLLATE NOCASE,
    QuestionID     "[INTEGER]" DEFAULT (0) 
                               NOT NULL
                               COLLATE NOCASE,
    QuestionNumber "[INTEGER]" DEFAULT (0) 
