                               COLLATE NOCASE,
    PRIMARY KEY (
        WebID,
        QuestionID
    ),
    CONSTRAINT Unq_WebQuestion_QuestionID UNIQUE (
        QuestionID COLLATE NOCASE ASC
    )
);

