-- Table: Tag
DROP TABLE IF EXISTS Tag;

CREATE TABLE IF NOT EXISTS Tag (
    TagId       TEXT    NOT NULL
                        PRIMARY KEY,
    TagName     TEXT    NOT NULL,
    SortIndex   INTEGER NOT NULL
                        DEFAULT 0,
    IsActive    INTEGER NOT NULL
                        DEFAULT 1,
    ParentTagId TEXT    NULL,
    TagKey      TEXT    NULL,
    TagPath     TEXT    NULL,
    NodeType    TEXT    NOT NULL
                        DEFAULT 'Normal',
    FOREIGN KEY (
        ParentTagId
    )
    REFERENCES Tag (TagId),
    CONSTRAINT CK_Tag_IsActive CHECK (IsActive IN (0, 1) ),
    CONSTRAINT CK_Tag_NodeType CHECK (NodeType IN ('Normal', 'System', 'Virtual') ) 
);

