-- Table: TagAssignment
DROP TABLE IF EXISTS TagAssignment;

CREATE TABLE IF NOT EXISTS TagAssignment (
    TagAssignmentId TEXT    NOT NULL
                            PRIMARY KEY,
    TagId           TEXT    NOT NULL,
    EntityType      TEXT    NOT NULL,
    EntityId        TEXT    NOT NULL,
    SortIndex       INTEGER NOT NULL
                            DEFAULT 0,
    IsActive        INTEGER NOT NULL
                            DEFAULT 1,
    FOREIGN KEY (
        TagId
    )
    REFERENCES Tag (TagId),
    CONSTRAINT CK_TagAssignment_IsActive CHECK (IsActive IN (0, 1) ) 
);

