-- Table: TxnStatusLog
DROP TABLE IF EXISTS TxnStatusLog;

CREATE TABLE IF NOT EXISTS TxnStatusLog (
    TxnStatusLogId INTEGER PRIMARY KEY AUTOINCREMENT,
    TransactionId  INTEGER NOT NULL,
    OldStatus      TEXT,
    NewStatus      TEXT    NOT NULL,
    ReasonCode     TEXT    NOT NULL,
    ReasonText     TEXT,
    ChangedUtc     TEXT    NOT NULL,
    ChangedBy      TEXT,
    Source         TEXT,
    FOREIGN KEY (
        TransactionId
    )
    REFERENCES Txn (TransactionId) 
);

