    WebsiteId TEXT    NOT NULL
                      PRIMARY KEY,
    Name      TEXT    NOT NULL,
    Url       TEXT    NOT NULL,
    SortIndex INTEGER NOT NULL
                      DEFAULT 0,
    Notes     TEXT    NULL,
    IsActive  INTEGER NOT NULL
                      DEFAULT 1
);

