);


-- View: vw_AccountWithTag
DROP VIEW IF EXISTS vw_AccountWithTag;
CREATE VIEW IF NOT EXISTS vw_AccountWithTag AS
    SELECT a.AccountId,
           a.AccountNickname,
           a.BankId,
           a.SortIndex,
           COALESCE(t.TagName, 'None') AS TagName,
           COALESCE(t.SortIndex, 9999) AS TagSortIndex
      FROM Account a
           LEFT JOIN
           TagAssignment ta ON ta.EntityType = 'Account' AND
                               ta.EntityId = a.AccountId AND
                               ta.IsActive = 1
           LEFT JOIN
           Tag t ON t.TagId = ta.TagId AND
                    t.IsActive = 1;


-- View: vw_AccountWithTags
DROP VIEW IF EXISTS vw_AccountWithTags;
CREATE VIEW IF NOT EXISTS vw_AccountWithTags AS
    SELECT a.AccountId,
           a.AccountNickname,
           a.BankId,
           a.SortIndex,
           t.TagId,
           t.TagName,
           t.SortIndex AS TagSortIndex,
           ta.SortIndex AS AssignmentSortIndex
      FROM Account a
           LEFT JOIN
           TagAssignment ta ON ta.EntityType = 'Account' AND
                               ta.EntityId = a.AccountId AND
                               ta.IsActive = 1
           LEFT JOIN
           Tag t ON t.TagId = ta.TagId AND
                    t.IsActive = 1;


-- View: vw_BudgetTemplatePayees
DROP VIEW IF EXISTS vw_BudgetTemplatePayees;
CREATE VIEW IF NOT EXISTS vw_BudgetTemplatePayees AS
    SELECT PayeeId,
           PayeeName,
           SortIndex
      FROM Payee
     WHERE IncludeInBudgetTemplate = 1 AND
           IsActive = 1
     ORDER BY SortIndex,
              PayeeName;


-- View: vw_PayeeWithTag
DROP VIEW IF EXISTS vw_PayeeWithTag;
CREATE VIEW IF NOT EXISTS vw_PayeeWithTag AS
    SELECT p.PayeeId,
           p.PayeeName,
           p.SortIndex,
           COALESCE(t.TagName, 'None') AS TagName,
           COALESCE(t.SortIndex, 9999) AS TagSortIndex
      FROM Payee p
           LEFT JOIN
           TagAssignment ta ON ta.EntityType = 'Payee' AND
                               ta.EntityId = p.PayeeId AND
                               ta.IsActive = 1
           LEFT JOIN
           Tag t ON t.TagId = ta.TagId AND
                    t.IsActive = 1;


-- View: vw_PayeeWithTags
DROP VIEW IF EXISTS vw_PayeeWithTags;
CREATE VIEW IF NOT EXISTS vw_PayeeWithTags AS
    SELECT p.PayeeId,
           p.PayeeName,
           p.SortIndex,
           t.TagId,
           t.TagName,
           t.SortIndex AS TagSortIndex,
           ta.SortIndex AS AssignmentSortIndex
      FROM Payee p
           LEFT JOIN
           TagAssignment ta ON ta.EntityType = 'Payee' AND
                               ta.EntityId = p.PayeeId AND
                               ta.IsActive = 1
           LEFT JOIN
           Tag t ON t.TagId = ta.TagId AND
                    t.IsActive = 1;


-- View: vw_TagAssignmentExpanded
DROP VIEW IF EXISTS vw_TagAssignmentExpanded;
CREATE VIEW IF NOT EXISTS vw_TagAssignmentExpanded AS
    SELECT ta.TagAssignmentId,
           ta.TagId,
           t.TagName,
           t.SortIndex AS TagSortIndex,
           ta.EntityType,
           ta.EntityId,
           ta.SortIndex AS AssignmentSortIndex,
           ta.IsActive AS AssignmentIsActive,
           t.IsActive AS TagIsActive
      FROM TagAssignment ta
           JOIN
           Tag t ON t.TagId = ta.TagId;


-- View: vw_WebsiteTags
DROP VIEW IF EXISTS vw_WebsiteTags;
CREATE VIEW IF NOT EXISTS vw_WebsiteTags AS
    SELECT ta.EntityId AS WebsiteId,
           t.TagId,
           t.TagName,
           t.SortIndex
      FROM TagAssignment ta
           JOIN
           Tag t ON t.TagId = ta.TagId
     WHERE ta.EntityType = 'Website' AND
           ta.IsActive = 1 AND
           t.IsActive = 1
     ORDER BY t.SortIndex,
              t.TagName;


-- View: vw_WebsiteWithTag
DROP VIEW IF EXISTS vw_WebsiteWithTag;
CREATE VIEW IF NOT EXISTS vw_WebsiteWithTag AS
    SELECT w.WebsiteId,
           w.Name,
           w.Url,
           COALESCE(t.TagName, 'None') AS TagName,
           COALESCE(t.SortIndex, 9999) AS TagSortIndex
      FROM Website w
           LEFT JOIN
           TagAssignment ta ON ta.EntityType = 'Website' AND
                               ta.EntityId = w.WebsiteId AND
                               ta.IsActive = 1
           LEFT JOIN
           Tag t ON t.TagId = ta.TagId AND
                    t.IsActive = 1;


-- View: vw_WebsiteWithTags
DROP VIEW IF EXISTS vw_WebsiteWithTags;
CREATE VIEW IF NOT EXISTS vw_WebsiteWithTags AS
    SELECT w.WebsiteId,
           w.Name,
           w.Url,
           t.TagId,
           t.TagName,
           t.SortIndex AS TagSortIndex,
           ta.SortIndex AS AssignmentSortIndex
      FROM Website w
           LEFT JOIN
           TagAssignment ta ON ta.EntityType = 'Website' AND
                               ta.EntityId = w.WebsiteId AND
                               ta.IsActive = 1
           LEFT JOIN
           Tag t ON t.TagId = ta.TagId AND
                    t.IsActive = 1;


COMMIT TRANSACTION;
PRAGMA foreign_keys = on;
